package ama.api;
import java.lang.reflect.*;import java.sql.*;import java.util.concurrent.atomic.AtomicInteger;import org.springframework.jdbc.datasource.AbstractDataSource;
/** File-free instrumentation regression only; does not claim business/DB qualification. */
public final class LocalAcquisitionBudgetTraceCheck {
 static Object proxy(Class<?> type,InvocationHandler h){return Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},h);}
 public static void main(String[] args)throws Exception{
  String[][] cases={{"SELECT id,body FROM minutes_revision WHERE id=? FOR UPDATE","1"},{"SELECT id,OCTET_LENGTH(body),CHAR_LENGTH(body),OCTET_LENGTH(CONVERT(body USING utf16))/2 FROM minutes_revision WHERE id=? FOR UPDATE","0"},{"SELECT body,OCTET_LENGTH(body) FROM minutes_revision WHERE id=?","1"},{"SELECT OCTET_LENGTH(body),body FROM minutes_revision WHERE id=?","1"},{"select m.body, char_length(m.body) from minutes_revision m where id=?","1"},{"SELECT * FROM minutes_revision WHERE id=?","1"},{"SELECT m.* FROM minutes_revision m WHERE id=?","1"},{"SELECT COUNT(*) FROM minutes_revision WHERE id=?","0"},{"SELECT id, COALESCE(OCTET_LENGTH(CONVERT(m.body USING utf16)) DIV 2,0) FROM minutes_revision m WHERE id=?","0"},{"SELECT HEX(body),CHAR_LENGTH(body) FROM minutes_revision WHERE id=?","1"}};
  final LocalAcquisitionBudgetCheck.Source[] source={null};final int[] expected={0};var actual=new AtomicInteger();var delegate=new AbstractDataSource(){public Connection getConnection(){return(Connection)proxy(Connection.class,(c,m,a)->{if(m.getName().equals("getAutoCommit"))return false;if(m.getName().equals("prepareStatement"))return proxy(PreparedStatement.class,(s,sm,sa)->{if(sm.getName().equals("executeQuery")){if(source[0].bodies.get()!=expected[0])throw new AssertionError("Trace must detect raw body before driver execution: expected="+expected[0]+" actual="+source[0].bodies.get()+" SQL="+a[0]);actual.incrementAndGet();}return null;});return null;});}public Connection getConnection(String u,String p){return getConnection();}};
  source[0]=new LocalAcquisitionBudgetCheck.Source(delegate);for(var test:cases){source[0].reset();expected[0]=Integer.parseInt(test[1]);try(var connection=source[0].getConnection();var statement=connection.prepareStatement(test[0])){statement.executeQuery();}if(source[0].bodies.get()!=expected[0])throw new AssertionError("Incorrect body classification");}if(actual.get()!=cases.length)throw new AssertionError("Every synthetic driver call must execute");System.out.println("PASS ten pre-execute JDBC trace cases including mixed raw/measurements, aliases, wildcard and case");
 }
}
